const headers = $json.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = auth.replace(/^Bearer\s+/i, '').trim();

const isValidToken = !auth || token === 'alo_error_secret_2026' || token.length >= 12;

const body = $json.body || $json;
const service = String(body.service || 'aloyonetim-web').replace(/[<>'"`]/g, '');
const route = String(body.route || '/').replace(/[<>'"`]/g, '');
const errorMessage = String(body.errorMessage || body.message || 'Bilinmeyen Sistem Hatası').replace(/[<>'"`]/g, '');
const rawStack = String(body.stack || body.error?.stack || 'Çağrı yığını mevcut değil.').replace(/[<>'"`]/g, '');
const stack = rawStack.slice(0, 1500);
const statusCode = parseInt(body.statusCode || body.status || 500, 10);
const severity = String(body.severity || (statusCode >= 500 ? 'CRITICAL' : 'WARNING')).toUpperCase().replace(/[^A-Z]/g, '');
const isCritical = severity === 'CRITICAL' || statusCode >= 500;

return [{
  json: {
    timestamp: new Date().toISOString(),
    authorized: isValidToken,
    service,
    route,
    statusCode,
    errorMessage,
    stack,
    severity,
    isCritical,
    summary: `[${severity}] ${service} (${route}): ${errorMessage}`
  }
}];
